import copy
import unittest
from flowledger.normalize import normalize

class NormalizeTests(unittest.TestCase):
    def test_sorted_fresh_trimmed_values(self):
        rows = [{'id':' b ', 'cents':-7, 'tag':' x '}, {'id':'a','cents':0,'tag':'y'}]
        before = copy.deepcopy(rows)
        result = normalize(rows)
        self.assertEqual(result, [{'id':'a','cents':0,'tag':'y'}, {'id':'b','cents':-7,'tag':'x'}])
        self.assertEqual(rows, before)
        self.assertIsNot(result, rows)
        self.assertTrue(all(a is not b for a in result for b in rows))
    def test_empty(self):
        self.assertEqual(normalize([]), [])
    def test_duplicate_normalized_id(self):
        with self.assertRaises(ValueError):
            normalize([{'id':' a','cents':2,'tag':'x'}, {'id':'a ','cents':4,'tag':'y'}])
    def test_bad_containers_fields_and_types(self):
        bad = [None, {}, (), 'abc', [None], [{}], [{'id':'a','tag':'x'}],
               [{'id':'a','cents':1,'tag':'x','extra':True}]]
        for row in bad:
            with self.subTest(row=row), self.assertRaises(ValueError): normalize(row)
    def test_bad_field_values(self):
        good = {'id':'a','cents':1,'tag':'x'}
        for field, values in [('id',[None,0,'',' ']), ('tag',[None,False,'',' ']),
                              ('cents',[None,True,1.0,'2'])]:
            for value in values:
                with self.subTest(field=field,value=value), self.assertRaises(ValueError):
                    normalize([dict(good, **{field:value})])
    def test_rejection_does_not_mutate_earlier_rows(self):
        rows = [{'id':' a ','cents':2,'tag':' x '}, {'id':'bad','cents':True,'tag':'y'}]
        before = copy.deepcopy(rows)
        with self.assertRaises(ValueError): normalize(rows)
        self.assertEqual(rows, before)

