import copy
import unittest
from unittest.mock import patch
from flowledger.report import summarize

class ReportTests(unittest.TestCase):
    def test_signed_group_totals_and_exact_keys(self):
        rows = [{'id':'c','cents':8,'tag':' z '}, {'id':'a','cents':-3,'tag':'a'},
                {'id':'b','cents':2,'tag':'z'}]
        before = copy.deepcopy(rows)
        result = summarize(rows)
        self.assertEqual(result, {'count':3,'total_cents':7,'by_tag':{
            'a':{'count':1,'total_cents':-3}, 'z':{'count':2,'total_cents':10}}})
        self.assertEqual(list(result['by_tag']), ['a','z'])
        self.assertEqual(rows, before)
    def test_empty(self):
        self.assertEqual(summarize([]), {'count':0,'total_cents':0,'by_tag':{}})
    def test_invalid_records_reuse_normalization(self):
        for rows in [None, [{'id':'a','cents':False,'tag':'x'}],
                     [{'id':'a','cents':1,'tag':'x'}, {'id':' a ','cents':2,'tag':'y'}]]:
            with self.subTest(rows=rows), self.assertRaises(ValueError): summarize(rows)
    def test_uses_normalizer_result(self):
        with patch('flowledger.report.normalize', return_value=[{'id':'n','cents':11,'tag':'normalized'}]) as call:
            self.assertEqual(summarize(['input']), {'count':1,'total_cents':11,'by_tag':{
                'normalized':{'count':1,'total_cents':11}}})
            call.assert_called_once_with(['input'])
